  const match=url.pathname.match(/^\/api\/rooms\/([A-Z0-9]{6})(?:\/(join|move|rematch|leave|resume))?$/);if(!match)return json({error:'Room route not found.'},404);const [,code,operation]=match;const {room,etag}=await roomRead(env,code);
